/****************************************************************************
 * main.c — Campus Agent 主入口
 *
 * 两种运行模式：
 *   1. CLI 模式：nsh> campus_agent <command>
 *   2. UI 模式：nsh> campus_agent （无参数，启动 LVGL + 后台任务）
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <nuttx/timers/rtc.h>

#include <lvgl/lvgl.h>

#include "course_manager.h"
#include "reminder_engine.h"
#include "sedentary_monitor.h"
#include "ui_briefing.h"
#include "ui_common.h"
#include "popup.h"

/****************************************************************************
 * 屏幕参数
 ****************************************************************************/

#ifndef SCREEN_WIDTH
#define SCREEN_WIDTH  390
#endif

#ifndef SCREEN_HEIGHT
#define SCREEN_HEIGHT 450
#endif

/****************************************************************************
 * 全局 UI 对象
 ****************************************************************************/

static lv_obj_t *g_main_screen = NULL;
static lv_obj_t *g_briefing_cont = NULL;
static lv_obj_t *g_status_label = NULL;

/****************************************************************************
 * 读取 RTC
 ****************************************************************************/

static int get_current_time(int *weekday, int *hour, int *min)
{
  int fd = open("/dev/rtc0", O_RDONLY);
  if (fd < 0) return -1;

  struct rtc_time rt;
  int ret = ioctl(fd, RTC_RD_TIME, (unsigned long)&rt);
  close(fd);
  if (ret < 0) return -1;

  if (weekday) *weekday = rt.tm_wday == 0 ? 7 : rt.tm_wday;
  if (hour)    *hour    = rt.tm_hour;
  if (min)     *min     = rt.tm_min;
  return 0;
}

/****************************************************************************
 * UI: 状态栏
 ****************************************************************************/

static void create_status_bar(lv_obj_t *parent)
{
  g_status_label = lv_label_create(parent);
  lv_label_set_text(g_status_label, "Campus Agent");
  lv_obj_set_style_text_font(g_status_label, FONT_SMALL, 0);
  lv_obj_set_style_text_color(g_status_label, COLOR_TEXT_GRAY, 0);
  lv_obj_align(g_status_label, LV_ALIGN_TOP_MID, 0, 8);
}

/****************************************************************************
 * UI: 课程简报列表
 ****************************************************************************/

static void create_briefing_ui(lv_obj_t *parent)
{
  /* 容器 */

  g_briefing_cont = lv_obj_create(parent);
  lv_obj_set_size(g_briefing_cont, SCREEN_WIDTH - 20, SCREEN_HEIGHT - 100);
  lv_obj_align(g_briefing_cont, LV_ALIGN_TOP_MID, 0, 40);
  lv_obj_set_style_bg_color(g_briefing_cont, COLOR_BG_CARD, 0);
  lv_obj_set_style_bg_opa(g_briefing_cont, LV_OPA_COVER, 0);
  lv_obj_set_style_radius(g_briefing_cont, 12, 0);
  lv_obj_set_style_border_width(g_briefing_cont, 0, 0);
  lv_obj_set_style_pad_all(g_briefing_cont, 16, 0);
