static void refresh_briefing_ui(void)
{
  if (!g_briefing_cont) return;

  /* 清除旧内容 */

  lv_obj_clean(g_briefing_cont);

  int wd, h, m;
  if (get_current_time(&wd, &h, &m) < 0)
    {
      ui_create_label(g_briefing_cont, "RTC not available",
                      FONT_SMALL, COLOR_TEXT_RED);
      return;
    }

  const char *weekday_names[] =
    { "", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun" };

  /* 日期标题 */

  char date_buf[32];
  snprintf(date_buf, sizeof(date_buf), "%s  %02d:%02d",
           weekday_names[wd], h, m);
  ui_create_label(g_briefing_cont, date_buf,
                  FONT_LARGE, COLOR_TEXT_WHITE);

  /* 分隔线 */

  lv_obj_t *sep = lv_obj_create(g_briefing_cont);
  lv_obj_set_size(sep, 280, 1);
  lv_obj_set_style_bg_color(sep, COLOR_TEXT_GRAY, 0);
  lv_obj_set_style_bg_opa(sep, LV_OPA_30, 0);
  lv_obj_set_style_border_width(sep, 0, 0);

  /* 课程列表 */

  course_query_t states[10];
  int count = course_get_today_status(wd, h, m, states, 10);

  if (count == 0)
    {
      ui_create_label(g_briefing_cont, "No classes today",
                      FONT_MEDIUM, COLOR_TEXT_GREEN);
      ui_create_label(g_briefing_cont, "Enjoy your day!",
                      FONT_SMALL, COLOR_TEXT_GRAY);
      return;
    }

  for (int i = 0; i < count; i++)
    {
      const course_t *c = states[i].course;

      /* 单个课程卡片 */

      lv_obj_t *card = lv_obj_create(g_briefing_cont);
      lv_obj_set_size(card, 310, 60);
      lv_obj_set_style_radius(card, 8, 0);
      lv_obj_set_style_border_width(card, 0, 0);
      lv_obj_set_style_pad_all(card, 8, 0);

      if (states[i].is_happening)
        {
          lv_obj_set_style_bg_color(card, lv_color_hex(0x1B3A1B), 0);
        }
      else if (states[i].minutes_left < 0)
        {
          lv_obj_set_style_bg_color(card, lv_color_hex(0x2A2A2A), 0);
        }
      else
        {
          lv_obj_set_style_bg_color(card, lv_color_hex(0x1A2A3E), 0);
        }

      lv_obj_set_style_bg_opa(card, LV_OPA_COVER, 0);

      /* 状态图标 */

      const char *icon;
      lv_color_t icon_color;
      if (states[i].is_happening)
        {
          icon = "*";
          icon_color = COLOR_TEXT_RED;
        }
      else if (states[i].minutes_left < 0)
        {
          icon = "v";
          icon_color = COLOR_TEXT_GRAY;
        }
      else
        {
          icon = ">";
          icon_color = COLOR_TEXT_BLUE;
        }

      lv_obj_t *icon_label = lv_label_create(card);
      lv_label_set_text(icon_label, icon);
      lv_obj_set_style_text_font(icon_label, FONT_MEDIUM, 0);
      lv_obj_set_style_text_color(icon_label, icon_color, 0);
      lv_obj_align(icon_label, LV_ALIGN_LEFT_MID, 0, 0);

      /* 课程名 */

      lv_obj_t *name_label = lv_label_create(card);
      lv_label_set_text(name_label, c->name);
      lv_obj_set_style_text_font(name_label, FONT_SMALL, 0);
      lv_obj_set_style_text_color(name_label, COLOR_TEXT_WHITE, 0);
      lv_obj_align(name_label, LV_ALIGN_LEFT_MID, 24, -8);

      /* 时间 */

      char time_buf[32];
      snprintf(time_buf, sizeof(time_buf), "%02d:%02d-%02d:%02d  %s",
               c->start_hour, c->start_min,
               c->end_hour, c->end_min,
               c->location);

      lv_obj_t *time_label = lv_label_create(card);
      lv_label_set_text(time_label, time_buf);
      lv_obj_set_style_text_font(time_label, FONT_TINY, 0);
      lv_obj_set_style_text_color(time_label, COLOR_TEXT_GRAY, 0);
      lv_obj_align(time_label, LV_ALIGN_LEFT_MID, 24, 10);
    }
}

