/****************************************************************************
 * UI 模式：启动 LVGL + 后台任务
 ****************************************************************************/

static int run_ui_mode(void)
{
  printf("=== Campus Agent UI Mode ===\n");

  /* 检查 LVGL 是否已初始化 */

  if (lv_is_initialized())
    {
      printf("ERROR: LVGL already initialized.\n");
      printf("Stop other LVGL apps first.\n");
      return -1;
    }

  /* LVGL 初始化 */

  lv_init();
  lv_nuttx_dsc_t dsc;
  lv_nuttx_result_t result;
  lv_nuttx_dsc_init(&dsc);

  dsc.fb_path    = "/dev/lcd0";
  dsc.input_path = "/dev/input0";

  lv_nuttx_init(&dsc, &result);
  if (result.disp == NULL)
    {
      printf("ERROR: display init failed\n");
      return -1;
    }

  printf("Display: %dx%d\n", SCREEN_WIDTH, SCREEN_HEIGHT);

  /* 初始化中文字体 */

  ui_font_init();

  /* 创建主界面 */

  g_main_screen = lv_screen_active();
  lv_obj_set_style_bg_color(g_main_screen, COLOR_BG_DARK, 0);
  lv_obj_set_style_bg_opa(g_main_screen, LV_OPA_COVER, 0);

  create_status_bar(g_main_screen);
  create_briefing_ui(g_main_screen);
  refresh_briefing_ui();

  /* 启动后台任务 */

  course_manager_init();
  reminder_engine_start();
  sedentary_monitor_start();

  /* 创建刷新定时器（每 30 秒刷新一次） */

  lv_timer_t *refresh_timer = lv_timer_create(
    ui_refresh_timer_cb, 30000, NULL);
  lv_timer_ready(refresh_timer);

  printf("UI ready. Background tasks started.\n");

  /* LVGL 主循环 */

  uint32_t idle;
  while (1)
    {
      idle = lv_timer_handler();
      idle = idle ? idle : 1;
      usleep(idle * 1000);
    }

  return 0;
}

