static void cmd_dump(void)
{
  course_manager_init();
  course_dump();
}

static void cmd_today(void)
{
  course_manager_init();
  int wd, h, m;
  if (get_current_time(&wd, &h, &m) < 0) return;

  const char *weekday_names[] =
    { "", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun" };

  printf("\n=== Today: %s %02d:%02d ===\n",
         weekday_names[wd], h, m);

  course_query_t states[10];
  int count = course_get_today_status(wd, h, m, states, 10);

  if (count == 0)
    {
      printf("No classes today.\n\n");
      return;
    }

  for (int i = 0; i < count; i++)
    {
      const course_t *c = states[i].course;
      const char *status = states[i].is_happening ? "IN PROGRESS" :
                           states[i].minutes_left < 0 ? "DONE" :
                           "UPCOMING";
      printf("  [%s] %02d:%02d-%02d:%02d  %-20s  %s\n",
             status,
             c->start_hour, c->start_min,
             c->end_hour, c->end_min,
             c->name, c->location);
    }
  printf("\n");
}

static void cmd_next(void)
{
  course_manager_init();
  int wd, h, m;
  if (get_current_time(&wd, &h, &m) < 0) return;

  course_query_t q;
  if (course_get_next(wd, h, m, &q) < 0)
    {
      printf("No more classes today.\n");
      return;
    }

  const course_t *c = q.course;
  if (q.is_happening)
    printf("Now: %s (%s) - IN PROGRESS\n", c->name, c->location);
  else
    printf("Next: %s (%s) at %02d:%02d (%d min)\n",
           c->name, c->location,
           c->start_hour, c->start_min, q.minutes_left);
}

static void cmd_set_time(int argc, char *argv[])
{
  if (argc < 4)
    {
      printf("Usage: campus_agent set_time <wd> <h> <m>\n");
      return;
    }

  int wd = atoi(argv[2]);
  int h  = atoi(argv[3]);
  int m  = argc > 4 ? atoi(argv[4]) : 0;

  int fd = open("/dev/rtc0", O_RDONLY);
  if (fd < 0) { printf("ERROR: RTC\n"); return; }

  struct rtc_time rt;
  ioctl(fd, RTC_RD_TIME, (unsigned long)&rt);
  rt.tm_wday = wd == 7 ? 0 : wd;
  rt.tm_hour = h;
  rt.tm_min  = m;
  rt.tm_sec  = 0;
  ioctl(fd, RTC_SET_TIME, (unsigned long)&rt);
  close(fd);

  const char *weekday_names[] =
    { "Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat" };
  printf("RTC set to: %s %02d:%02d\n",
         weekday_names[rt.tm_wday], h, m);
}

static void cmd_help(void)
{
  printf("\n=== Campus Agent (Team 307) ===\n");
  printf("Usage: campus_agent [command]\n\n");
  printf("No args = UI mode (LVGL + background tasks)\n\n");
  printf("CLI Commands:\n");
  printf("  dump                   Print course schedule\n");
  printf("  today                  Show today's courses\n");
  printf("  next                   Show next course\n");
  printf("  briefing               Daily briefing\n");
  printf("  set_time <wd> <h> <m>  Set RTC\n");
  printf("  remind                 Start reminder\n");
  printf("  stop                   Stop reminder\n");
  printf("  sedentary              Start sedentary\n");
  printf("  sed_stop               Stop sedentary\n");
  printf("  sed_status             Sedentary status\n");
  printf("  test_vibrate           Test vibration\n");
  printf("  test_imu               Test IMU\n");
  printf("  help                   Show this help\n");
  printf("\n");
}

/****************************************************************************
 * 主函数
 ****************************************************************************/

int main(int argc, char *argv[])
{
  /* 无参数 = UI 模式 */

  if (argc < 2)
    {
      return run_ui_mode();
    }

  /* CLI 模式 */

  if (strcmp(argv[1], "dump") == 0)
    cmd_dump();
  else if (strcmp(argv[1], "today") == 0)
    cmd_today();
  else if (strcmp(argv[1], "next") == 0)
    cmd_next();
  else if (strcmp(argv[1], "briefing") == 0)
    {
      course_manager_init();
      ui_briefing_show_cli();
    }
  else if (strcmp(argv[1], "set_time") == 0)
    cmd_set_time(argc, argv);
  else if (strcmp(argv[1], "remind") == 0)
    {
      course_manager_init();
      reminder_engine_start();
      printf("Reminder engine started.\n");
    }
  else if (strcmp(argv[1], "stop") == 0)
    reminder_engine_stop();
  else if (strcmp(argv[1], "status") == 0)
    {
      printf("Reminder: %s\n",
             reminder_engine_is_running() ? "RUNNING" : "STOPPED");
    }
  else if (strcmp(argv[1], "test_vibrate") == 0)
    reminder_engine_test();
  else if (strcmp(argv[1], "sedentary") == 0)
    {
      sedentary_monitor_start();
      printf("Sedentary monitor started.\n");
    }
  else if (strcmp(argv[1], "sed_stop") == 0)
    sedentary_monitor_stop();
  else if (strcmp(argv[1], "sed_status") == 0)
    {
      printf("Sedentary: %s\n",
             sedentary_monitor_is_running() ? "RUNNING" : "STOPPED");
      const sedentary_state_t *st = sedentary_get_state();
      printf("Sitting: %d min, Alert: %d\n",
             st->sitting_minutes, st->alert_level);
    }
  else if (strcmp(argv[1], "test_imu") == 0)
    sedentary_test_imu();
  else if (strcmp(argv[1], "help") == 0)
    cmd_help();
  else
    {
      printf("Unknown command: %s\n", argv[1]);
      cmd_help();
    }

  return 0;
}

