/****************************************************************************
 * 读取 RTC
 ****************************************************************************/

static int read_rtc(int *wd, int *h, int *m, int *s)
{
  int fd = open("/dev/rtc0", O_RDONLY);
  if (fd < 0) return -1;
  struct rtc_time rt;
  int ret = ioctl(fd, RTC_RD_TIME, (unsigned long)&rt);
  close(fd);
  if (ret < 0) return -1;
  if (wd) *wd = rt.tm_wday == 0 ? 7 : rt.tm_wday;
  if (h)  *h  = rt.tm_hour;
  if (m)  *m  = rt.tm_min;
  if (s)  *s  = rt.tm_sec;
  return 0;
}

