 ****************************************************************************/

static void refresh_course_list(void)
{
  if (!g_course_list) return;
  lv_obj_clean(g_course_list);

  int wd, h, m;
  if (read_rtc(&wd, &h, &m, NULL) < 0) return;

  const char *wd_names[] = {"","Mon","Tue","Wed","Thu","Fri","Sat","Sun"};

  course_query_t states[10];
  int count = course_get_today_status(wd, h, m, states, 10);

  if (count == 0)
    {
      lv_obj_t *lbl = lv_label_create(g_course_list);
      lv_label_set_text(lbl, "No classes today");
      lv_obj_set_style_text_font(lbl, FONT_MEDIUM, 0);
      lv_obj_set_style_text_color(lbl, COLOR_TEXT_GREEN, 0);
      lv_obj_center(lbl);
      return;
    }

  for (int i = 0; i < count; i++)
    {
      const course_t *c = states[i].course;

      /* 课程卡片 */

      lv_obj_t *card = lv_obj_create(g_course_list);
      lv_obj_set_size(card, 340, 64);
      lv_obj_set_style_radius(card, 10, 0);
      lv_obj_set_style_border_width(card, 0, 0);
      lv_obj_set_style_pad_all(card, 10, 0);
      lv_obj_set_flex_flow(card, LV_FLEX_FLOW_ROW);
      lv_obj_set_flex_align(card, LV_FLEX_ALIGN_START,
                            LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
      lv_obj_set_style_pad_column(card, 10, 0);

      /* 状态指示灯 */

      lv_obj_t *dot = lv_obj_create(card);
      lv_obj_set_size(dot, 12, 12);
      lv_obj_set_style_radius(dot, 6, 0);
      lv_obj_set_style_border_width(dot, 0, 0);

      if (states[i].is_happening)
        {
          lv_obj_set_style_bg_color(dot, COLOR_TEXT_RED, 0);
          lv_obj_set_style_bg_color(card, lv_color_hex(0x1B2A1B), 0);
        }
      else if (states[i].minutes_left < 0)
        {
          lv_obj_set_style_bg_color(dot, COLOR_TEXT_GRAY, 0);
          lv_obj_set_style_bg_color(card, lv_color_hex(0x1E1E2E), 0);
        }
      else
        {
          lv_obj_set_style_bg_color(dot, COLOR_TEXT_GREEN, 0);
          lv_obj_set_style_bg_color(card, lv_color_hex(0x1A2A3E), 0);
        }

      lv_obj_set_style_bg_opa(dot, LV_OPA_COVER, 0);
      lv_obj_set_style_bg_opa(card, LV_OPA_COVER, 0);

      /* 右侧文字区域 */

      lv_obj_t *txt_cont = lv_obj_create(card);
      lv_obj_set_size(txt_cont, 280, 44);
      lv_obj_set_style_bg_opa(txt_cont, LV_OPA_TRANSP, 0);
      lv_obj_set_style_border_width(txt_cont, 0, 0);
      lv_obj_set_style_pad_all(txt_cont, 0, 0);
      lv_obj_set_flex_flow(txt_cont, LV_FLEX_FLOW_COLUMN);
      lv_obj_set_flex_align(txt_cont, LV_FLEX_ALIGN_START,
                            LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
