      /* 课程名 */

      lv_obj_t *name = lv_label_create(txt_cont);
      lv_label_set_text(name, c->name);
      lv_obj_set_style_text_font(name, FONT_SMALL, 0);
      lv_obj_set_style_text_color(name, COLOR_TEXT_WHITE, 0);

      /* 时间 + 地点 */

      char info[64];
